typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static int N;
static ll *A;
static int *deg;
static int *head;
static Edge *edges;
static int ecnt = 0;

void add_edge(int u, int v) {
    edges[ecnt].to = v;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

/*
Returns the amount that must go from this node to its parent.
If impossible, sets ok = 0.
Root is handled specially after DFS.
*/
ll dfs(int u, int p, int *ok) {
    int child_count = 0;
    ll sum = 0;
    ll mx = 0;

    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (v == p) continue;
        ll x = dfs(v, u, ok);
        if (!*ok) return 0;
        child_count++;
        sum += x;
        if (x > mx) mx = x;
    }

    if (child_count == 0) {
        // leaf
        return A[u];
    }

    ll a = A[u];
    ll ret = 2 * a - sum;

    // Need nonnegative remaining flow to parent
    if (ret < 0) {
        *ok = 0;
        return 0;
    }

    // Internal pairing feasibility:
    // Let t = sum - a be total amount paired inside this node.
    // Need 0 <= t <= sum/2, and also t achievable w.r.t. largest child.
    // Equivalent to:
    //   a <= sum
    //   sum - a <= sum - mx  => a >= mx
    if (a > sum || a < mx) {
        *ok = 0;
        return 0;
    }

    return ret;
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;

    A = (ll*)malloc((N + 1) * sizeof(ll));
    deg = (int*)calloc(N + 1, sizeof(int));
    head = (int*)malloc((N + 1) * sizeof(int));
    edges = (Edge*)malloc((2 * (N - 1)) * sizeof(Edge));

    for (int i = 1; i <= N; i++) {
        scanf("%lld", &A[i]);
        head[i] = -1;
    }

    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
        deg[u]++;
        deg[v]++;
    }

    if (N == 2) {
        if (A[1] == A[2]) printf("YES\n");
        else printf("NO\n");
        free(A); free(deg); free(head); free(edges);
        return 0;
    }

    int root = 1;
    while (root <= N && deg[root] == 1) root++;

    int ok = 1;
    ll res = dfs(root, 0, &ok);

    if (ok && res == 0) printf("YES\n");
    else printf("NO\n");

    free(A);
    free(deg);
    free(head);
    free(edges);
    return 0;
}

