int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    if (n == 2) {
        if (a[0] == a[1]) cout << "YES\n";
        else cout << "NO\n";
        return 0;
    }

    // Find a non-leaf root
    int root = 0;
    while (g[root].size() == 1) root++;

    vector<long long> dp(n);
    vector<int> parent(n, -1);
    vector<int> order;
    order.reserve(n);

    // BFS/DFS to get order
    stack<int> st;
    st.push(root);
    parent[root] = root;
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        order.push_back(u);
        for (int v : g[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            st.push(v);
        }
    }

    // Process in reverse order
    bool possible = true;
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        if (g[u].size() == 1 && u != root) {
            dp[u] = a[u];
            continue;
        }
        long long sum_child = 0;
        long long max_child = 0;
        for (int v : g[u]) {
            if (v == parent[u]) continue;
            sum_child += dp[v];
            max_child = max(max_child, dp[v]);
        }
        long long x = a[u];
        if (sum_child < x) {
            possible = false;
            break;
        }
        long long pairs = sum_child - x;
        if (pairs > sum_child - max_child) {
            possible = false;
            break;
        }
        dp[u] = x - pairs;
    }

    if (possible && dp[root] == 0) cout << "YES\n";
    else cout << "NO\n";

    return 0;
}

