public class Main {
    static List<Integer>[] g;
    static long[] a;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            g[u].add(v);
            g[v].add(u);
        }
        a = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());

        // Find a leaf as root for easier handling
        int root = 0;
        for (int i = 0; i < n; i++) {
            if (g[i].size() == 1) {
                root = i;
                break;
            }
        }

        if (dfs(root, -1) == 0) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    static long dfs(int v, int p) {
        if (g[v].size() == 1 && p != -1) {
            // leaf
            return a[v];
        }
        long sum = 0;
        long max = 0;
        for (int to : g[v]) {
            if (to == p) continue;
            long val = dfs(to, v);
            sum += val;
            max = Math.max(max, val);
        }
        long stones = a[v];
        if (sum < stones || sum > stones * 2) {
            System.out.println("NO");
            System.exit(0);
        }
        long pairUp = stones - (sum - stones);
        if (pairUp < 0 || pairUp > stones) {
            System.out.println("NO");
            System.exit(0);
        }
        // check if pairing possible inside
        long other = sum - max;
        if (max > stones + other) {
            System.out.println("NO");
            System.exit(0);
        }
        return pairUp;
    }
}

