import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static int N;
    static long[] a;
    static ArrayList<Integer>[] g;
    static boolean possible = true;

    static long dfs(int v, int p) {
        ArrayList<Long> childVals = new ArrayList<>();
        long sum = 0;

        boolean isLeaf = (p != -1 && g[v].size() == 1) || (N == 1);
        if (isLeaf) return a[v];

        for (int to : g[v]) {
            if (to == p) continue;
            long x = dfs(to, v);
            if (!possible) return 0;
            childVals.add(x);
            sum += x;
        }

        if (p == -1 && g[v].size() == 1) {
            // root has one child: whole tree is a path endpoint
            return childVals.get(0);
        }

        long maxChild = 0;
        for (long x : childVals) maxChild = Math.max(maxChild, x);

        long x = 2L * a[v] - sum; // amount passed upward

        if (x < 0 || x > a[v]) {
            possible = false;
            return 0;
        }

        long paired = sum - a[v]; // amount consumed at v by pairing children
        if (paired < 0) {
            possible = false;
            return 0;
        }

        // Need to be able to form paired units using distinct children
        if (paired > sum - maxChild) {
            possible = false;
            return 0;
        }

        return x;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        if (N == 1) {
            System.out.println(a[0] == 0 ? "YES" : "NO");
            return;
        }

        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }

        int root = 0;
        for (int i = 0; i < N; i++) {
            if (g[i].size() >= 2) {
                root = i;
                break;
            }
        }

        long res = dfs(root, -1);
        if (!possible) {
            System.out.println("NO");
            return;
        }

        System.out.println(res == 0 ? "YES" : "NO");
    }
}
